import express from "express";
import { Telegraf } from "telegraf";

import { config } from "./config";
import type { BotContext } from "./bot/context";

export async function startServer(bot: Telegraf<BotContext>) {
  if (!config.useWebhook) {
    await bot.launch();
    return;
  }

  const app = express();
  const webhookPath = `/telegram/${config.webhookSecret}`;

  app.use(webhookPath, bot.webhookCallback(webhookPath));

  app.get("/health", (_req, res) => {
    res.json({ ok: true });
  });

  app.listen(config.port, async () => {
    await bot.telegram.setWebhook(`${config.webhookDomain}${webhookPath}`);
    console.log(`Webhook server is listening on port ${config.port}`);
  });
}
