import { Markup } from "telegraf";

import type { QuestionWithStudent, StudentSummary } from "../types";
import { formatAnonLabel, formatStudentSummary } from "./anon";

export const studentMainKeyboard = Markup.keyboard([
  [Markup.button.text("Задать вопрос")],
  [Markup.button.text("Помощь")]
]).resize();

export const teacherMainKeyboard = Markup.keyboard([
  [Markup.button.text("Новые вопросы"), Markup.button.text("Студенты")],
  [Markup.button.text("Помощь")]
]).resize();

export function questionsKeyboard(questions: QuestionWithStudent[]) {
  return Markup.inlineKeyboard(
    questions.map((question) =>
      [Markup.button.callback(`#${question.id} · ${question.status === "pending" ? "ожидает" : "отвечен"} · ${formatAnonLabel(question.studentId)}`, `question:${question.id}`)]
    )
  );
}

export function questionActionsKeyboard(questionId: number, studentId: number, answered: boolean) {
  const rows = [];

  if (!answered) {
    rows.push([Markup.button.callback("Ответить", `answer:${questionId}`)]);
  }

  rows.push([Markup.button.callback("Написать студенту", `message_student:${studentId}`)]);
  rows.push([Markup.button.callback("К списку вопросов", "menu:questions")]);

  return Markup.inlineKeyboard(rows);
}

export function studentsKeyboard(students: StudentSummary[]) {
  return Markup.inlineKeyboard(
    students.map((student) => {
      const label = `${formatStudentSummary(student)} · ${student.questionsCount}`;
      return [Markup.button.callback(label, `student:${student.id}`)];
    })
  );
}

export function studentActionsKeyboard(studentId: number) {
