import { config } from "../config";
import { upsertUser } from "../db";
import type { UserRecord, UserRole } from "../types";
import type { BotContext } from "./context";

export function getTelegramUser(ctx: BotContext) {
  const from = ctx.from;
  if (!from) {
    throw new Error("Telegram update does not have a sender");
  }

  return from;
}

export function getRole(telegramId: number): UserRole {
  return telegramId === config.teacherChatId ? "teacher" : "student";
}

export function ensureUser(ctx: BotContext): UserRecord {
  const from = getTelegramUser(ctx);
  return upsertUser({
    telegramId: from.id,
    username: from.username ?? null,
    firstName: from.first_name ?? null,
    lastName: from.last_name ?? null,
    role: getRole(from.id)
  });
}

export function isTeacher(ctx: BotContext): boolean {
  return getTelegramUser(ctx).id === config.teacherChatId;
}
