import { Context, session } from "telegraf";

type StudentSessionState =
  | { mode: "idle" }
  | { mode: "awaiting_question" };

type TeacherSessionState =
  | { mode: "idle" }
  | { mode: "awaiting_answer"; questionId: number }
  | { mode: "awaiting_student_message"; studentId: number };

export type SessionData = {
  student: StudentSessionState;
  teacher: TeacherSessionState;
};

export type BotContext = Context & {
  session?: SessionData;
};

export const sessionMiddleware = session<SessionData, BotContext>({
  defaultSession: () => ({
    student: { mode: "idle" },
    teacher: { mode: "idle" }
  })
});
